using System.Globalization;
using System.Text.Json;
using System.Windows;
using System.Windows.Media;
using VisionFramework;
using VisionPluginContracts;
using W=System.Windows.Controls;
using Color=System.Windows.Media.Color;
using Brushes=System.Windows.Media.Brushes;
namespace VisionPlugins.Calibration;

public sealed class RotateCalibrationWindow:Window {
 readonly ToolEditorContext context;readonly RotateCalibrationPlugin plugin;readonly Dictionary<string,JsonElement> values;readonly W.TabControl tabs=new();readonly W.TextBlock result=new(){Margin=new Thickness(20),TextWrapping=TextWrapping.Wrap};bool building,running,continuous,closed;
 readonly W.Button once=new(){Name="ExecuteRotateCalibration",Content="执行",Width=66,Height=25},loop=new(){Name="ContinuousRotateCalibration",Content="连续执行",Width=76,Height=25};
 public RotateCalibrationWindow(ToolEditorContext context,RotateCalibrationPlugin plugin){this.context=context;this.plugin=plugin;values=plugin.Descriptor.Parameters.ToDictionary(p=>p.Name,p=>p.DefaultValue!.Value.Clone());foreach(var pair in context.Node.Parameters)values[pair.Key]=pair.Value.Clone();plugin.UpdateConfiguration(context,values);Width=420;Height=650;WindowStyle=WindowStyle.None;ResizeMode=ResizeMode.NoResize;Background=new SolidColorBrush(Color.FromRgb(242,243,245));FontFamily=new("Microsoft YaHei UI");FontSize=14;WindowStartupLocation=WindowStartupLocation.CenterOwner;
  foreach(string file in new[]{"Theme.xaml","ListViewComboBoxStyle.xaml","RecScrollBarStyle.xaml","LightControls.xaml"})Resources.MergedDictionaries.Add(new ResourceDictionary{Source=new Uri("pack://application:,,,/VisionPlugins.ImageSource;component/Resources/"+file)});
  var layout=new W.Grid();layout.RowDefinitions.Add(new(){Height=new GridLength(context.Mode==ToolEditorMode.Desktop?34:0)});layout.RowDefinitions.Add(new());layout.RowDefinitions.Add(new(){Height=new GridLength(32)});
  var title=new W.DockPanel{Background=new SolidColorBrush(Color.FromRgb(36,36,36))};var close=Button("×",()=>Close(),"CloseRotateCalibration");close.Width=44;close.FontSize=22;W.DockPanel.SetDock(close,W.Dock.Right);title.Children.Add(close);title.Children.Add(new W.TextBlock{Text=(context.DisplayIndex is int index?index+" ":"")+context.Node.Name,Foreground=Brushes.White,FontWeight=FontWeights.Bold,VerticalAlignment=VerticalAlignment.Center,Margin=new Thickness(10,0,0,0)});title.MouseLeftButtonDown+=(_,_)=>DragMove();layout.Children.Add(title);W.Grid.SetRow(tabs,1);layout.Children.Add(tabs);
  var commands=new W.StackPanel{Orientation=W.Orientation.Horizontal,HorizontalAlignment=System.Windows.HorizontalAlignment.Right,Margin=new Thickness(0,3,14,3)};loop.Click+=async(_,_)=>{if(continuous){continuous=false;return;}if(running)return;continuous=true;loop.Content="停止";do{await Execute();if(continuous&&!closed)await Task.Delay(1);}while(continuous&&!closed);loop.Content="连续执行";};once.Click+=async(_,_)=>await Execute();commands.Children.Add(Button("重置",()=>{foreach(var p in plugin.Descriptor.Parameters.Where(p=>!p.Name.StartsWith("Cached",StringComparison.Ordinal)))values[p.Name]=p.DefaultValue!.Value.Clone();Apply();Build();},"ResetRotate"));commands.Children.Add(loop);commands.Children.Add(once);commands.Children.Add(Button("确定",()=>Close(),"ConfirmRotateCalibration"));W.Grid.SetRow(commands,2);layout.Children.Add(commands);Content=new W.Border{BorderBrush=Brushes.OrangeRed,BorderThickness=new Thickness(0,context.Mode==ToolEditorMode.Desktop?1:0,0,0),Child=layout};Closed+=(_,_)=>{closed=true;continuous=false;};Build();
 }
 static W.Button Button(string text,Action action,string name=""){var button=new W.Button{Name=name,Content=text,MinWidth=28,Height=25,Margin=new Thickness(2,0,0,0)};button.Click+=(_,_)=>action();return button;}
 void Apply(){plugin.UpdateConfiguration(context,values);context.Apply(values.ToDictionary(p=>p.Key,p=>p.Value.Clone()));}
 void Set<T>(string key,T value){values[key]=JsonSerializer.SerializeToElement(value);Apply();}
 int I(string name)=>values[name].GetInt32();bool B(string name)=>values[name].GetBoolean();
 static void Header(W.Panel parent,string label)=>parent.Children.Add(new W.TextBlock{Text=label,FontWeight=FontWeights.Bold,Margin=new Thickness(0,12,0,12)});
 static void Row(W.Panel parent,string caption,FrameworkElement field){var row=new W.Grid{MinHeight=35};row.ColumnDefinitions.Add(new(){Width=new GridLength(128)});row.ColumnDefinitions.Add(new());row.Children.Add(new W.TextBlock{Text=caption,Foreground=new SolidColorBrush(Color.FromRgb(98,103,108)),VerticalAlignment=VerticalAlignment.Center});field.VerticalAlignment=VerticalAlignment.Center;W.Grid.SetColumn(field,1);row.Children.Add(field);parent.Children.Add(row);}
 W.StackPanel Page(string name,string header){var rows=new W.StackPanel{Margin=new Thickness(24,8,24,14)};tabs.Items.Add(new W.TabItem{Name=name,Header=header,Content=new W.ScrollViewer{VerticalScrollBarVisibility=W.ScrollBarVisibility.Auto,HorizontalScrollBarVisibility=W.ScrollBarVisibility.Disabled,Content=rows}});return rows;}
 string InputLabel(string key)=>context.SubscriptionLabel?.Invoke(key,false)??"";
 void Input(W.Panel parent,string key,string label,bool text=false){bool integer=key is "RotNum" or "RefreshSignal";var panel=new W.DockPanel();var link=Button("↗",()=>{context.PickSubscription?.Invoke(this,key,false,integer?DataKind.Integer:text?DataKind.Text:DataKind.NumberArray);Build();},"Subscribe"+key);W.DockPanel.SetDock(link,W.Dock.Right);panel.Children.Add(link);var edit=new W.TextBox{Name="Input"+key,Height=28,VerticalContentAlignment=VerticalAlignment.Center,Text=integer?context.InputInteger?.Invoke(key)?.ToString(CultureInfo.InvariantCulture)??InputLabel(key):text?context.InputText?.Invoke(key)??InputLabel(key):context.InputNumbers?.Invoke(key) is {} numbers?string.Join(", ",numbers.Select(v=>v.ToString("G9",CultureInfo.InvariantCulture))):InputLabel(key)};edit.LostKeyboardFocus+=(_,_)=>{if(building||closed)return;Safe(()=>{if(integer)context.SetInputInteger?.Invoke(key,string.IsNullOrWhiteSpace(edit.Text)?null:int.Parse(edit.Text,CultureInfo.InvariantCulture));else if(text)context.SetInputText?.Invoke(key,string.IsNullOrEmpty(edit.Text)?null:edit.Text);else context.SetInputNumbers?.Invoke(key,string.IsNullOrWhiteSpace(edit.Text)?null:edit.Text.Split([',','，',';'],StringSplitOptions.RemoveEmptyEntries).Select(s=>double.Parse(s,CultureInfo.InvariantCulture)).ToArray());Build();});};panel.Children.Add(edit);Row(parent,label,panel);}
 void PairInput(W.Panel parent,string x,string y,string caption){var field=Button(string.IsNullOrEmpty(InputLabel(x))&&string.IsNullOrEmpty(InputLabel(y))?"请选择":InputLabel(x)+" / "+InputLabel(y),()=>{var dialog=new Window{Title=caption,Owner=this,Width=420,Height=180,WindowStartupLocation=WindowStartupLocation.CenterOwner};var rows=new W.StackPanel{Margin=new Thickness(16)};void Coordinate(string key,string label){var panel=new W.DockPanel();var select=Button("↗",()=>{context.PickSubscription?.Invoke(dialog,key,false,DataKind.NumberArray);Build();});W.DockPanel.SetDock(select,W.Dock.Right);panel.Children.Add(select);var edit=new W.TextBox{Text=context.InputNumbers?.Invoke(key) is {} numbers?string.Join(",",numbers.Select(v=>v.ToString(CultureInfo.InvariantCulture))):"",Height=27};edit.LostKeyboardFocus+=(_,_)=>Safe(()=>context.SetInputNumbers?.Invoke(key,string.IsNullOrWhiteSpace(edit.Text)?null:edit.Text.Split(',').Select(v=>double.Parse(v,CultureInfo.InvariantCulture)).ToArray()));panel.Children.Add(edit);Row(rows,label,panel);}Coordinate(x,"X");Coordinate(y,"Y");rows.Children.Add(Button("确定",()=>dialog.Close()));dialog.Content=rows;dialog.ShowDialog();Build();},"InputPair"+x);field.HorizontalContentAlignment=System.Windows.HorizontalAlignment.Left;Row(parent,caption,field);}

 void Build(){building=true;try{if(result.Parent is W.Panel oldResultParent)oldResultParent.Children.Remove(result);tabs.Items.Clear();var basic=Page("RotateBasic","基本参数");Header(basic,"图像源");Row(basic,"输入图像",Button(string.IsNullOrEmpty(InputLabel("InputImage"))?"请选择":InputLabel("InputImage"),()=>{context.PickSubscription?.Invoke(this,"InputImage",false,DataKind.Image);Build();},"SubscribeInputImage"));Header(basic,"拟合点");var modes=new W.StackPanel{Orientation=W.Orientation.Horizontal};for(int i=0;i<2;i++){int mode=i;var radio=new W.RadioButton{Name="InputWay"+i,Content=i==0?"按点输入":"按坐标输入",IsChecked=I("InputWay")==i,Style=(Style)FindResource("LightRadio"),Margin=new Thickness(0,0,16,0)};radio.Checked+=(_,_)=>{if(!building){Set("InputWay",mode);Build();}};modes.Children.Add(radio);}Row(basic,"图像点输入",modes);if(I("InputWay")==0)PairInput(basic,"ImagePointX","ImagePointY","图像点");else{Input(basic,"ImagePointX","图像坐标 X");Input(basic,"ImagePointY","图像坐标 Y");}Input(basic,"WorldRotateAngle","物理旋转角度");Input(basic,"RotNum","旋转次数");Header(basic,"标定文件");var reverse=new W.CheckBox{Name="RevOutputFlag",Content="反向输出",Style=(Style)FindResource("LightSwitch"),IsChecked=B("RevOutputFlag"),Margin=new Thickness(0,3,0,3)};reverse.Checked+=(_,_)=>{if(!building)Set("RevOutputFlag",true);};reverse.Unchecked+=(_,_)=>{if(!building)Set("RevOutputFlag",false);};Row(basic,"反向输出",reverse);var file=new W.DockPanel();var browse=Button("…",()=>{var dialog=new Microsoft.Win32.OpenFileDialog{Filter=".xml|*.xml;*.iwcal",Multiselect=false};if(dialog.ShowDialog(this)==true){Set("FilePath",dialog.FileName);Build();}},"BrowseRotateFile");W.DockPanel.SetDock(browse,W.Dock.Right);file.Children.Add(browse);var path=new W.TextBox{Name="FilePath",Height=28,Text=values["FilePath"].GetString()??""};path.LostKeyboardFocus+=(_,_)=>{if(!building&&!closed)Set("FilePath",path.Text);};file.Children.Add(path);Row(basic,"文件路径",file);Input(basic,"RefreshSignal","刷新信号");var resultPage=Page("RotateResults","结果");resultPage.Children.Add(new ToolTextDisplayEditor(context,ToolDisplayService.Read(values,plugin.DisplayDefinition),settings=>{values[ToolDisplayService.SettingsParameter]=ToolDisplayService.Serialize(settings);Apply();}));tabs.SelectedIndex=0;}finally{building=false;}}
 void Safe(Action action){try{action();}catch(Exception ex){System.Windows.MessageBox.Show(this,ex.Message,"旋转标定");}}
 async Task Execute(){if(running||closed)return;running=true;once.IsEnabled=false;try{var record=await context.Run(values.ToDictionary(p=>p.Key,p=>p.Value.Clone()));result.Text=string.Join(Environment.NewLine,record.Outputs.Select(p=>p.Key+": "+Convert.ToString(p.Value.Value,CultureInfo.InvariantCulture)));}catch(Exception e){continuous=false;System.Windows.MessageBox.Show(this,e.Message,"执行失败");}finally{running=false;once.IsEnabled=!continuous;}}
}




